package com.acttub.actingapi.auth;
import java.io.IOException; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import com.acttub.actingapi.web.ApiException;
/** Bearer 진입점에서 Spring ProblemDetail 대신 기존 detail 문자열을 직접 보장한다. */
@Component public class AccessTokenFilter extends OncePerRequestFilter {private final CurrentUserService users;public AccessTokenFilter(CurrentUserService users){this.users=users;}@Override protected boolean shouldNotFilter(HttpServletRequest request){String path=request.getRequestURI();if(path.equals("/health")||path.equals("/v2/auth/login")||path.equals("/v2/auth/refresh")||path.startsWith("/v3/api-docs"))return true;return request.getHeader("Authorization")==null&&!path.equals("/v2/auth/logout");}@Override protected void doFilterInternal(HttpServletRequest request,HttpServletResponse response,FilterChain chain)throws ServletException,IOException{try{users.require(request);chain.doFilter(request,response);}catch(ApiException e){response.setStatus(e.status());response.setContentType("application/json");response.setCharacterEncoding("UTF-8");response.getWriter().write("{\"detail\":\""+e.getMessage()+"\"}");}}}
